package com.tihai.controller;
import com.tihai.utils.*;import org.springframework.context.annotation.Configuration;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.web.servlet.config.annotation.*;import org.springframework.web.servlet.HandlerInterceptor;import javax.servlet.http.*;import org.springframework.http.*;import org.springframework.web.server.ResponseStatusException;
@Configuration public class AccountScopeConfiguration implements WebMvcConfigurer {
 @Autowired AccountRegistry registry;
 public void addInterceptors(InterceptorRegistry registrations){registrations.addInterceptor(new HandlerInterceptor(){public boolean preHandle(HttpServletRequest req,HttpServletResponse res,Object h)throws Exception{AccountScope.clear();try{if(req.getRequestURI().startsWith("/local/workspace/"))return true;registry.refresh();String p=req.getHeader("X-Study-Platform");if(p==null||p.isEmpty())p=registry.platform();try{AccountScope.bind(registry.resolve(p,req.getHeader("X-Study-Account")));}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"账号与平台选择无效");}if(req.getRequestURI().startsWith("/chaoxing")&&!"chaoxing".equals(AccountScope.platform()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"请切换到学习通");String path=req.getRequestURI();if(path.matches("/local/tasks/[^/]+/.*"))registry.requireTask(path.split("/")[3]);if(path.equals("/local/review/questions"))registry.requireTask(req.getParameter("course"));return true;}catch(Exception e){AccountScope.clear();throw e;}}public void afterCompletion(HttpServletRequest q,HttpServletResponse r,Object h,Exception e){AccountScope.clear();}}).addPathPatterns("/local/**","/chaoxing/**");}
}

